import ast

# Parse the code
tree = ast.parse(code)

# Look for 'in' and 'not in' operators
in_operators = []
not_in_operators = []

for node in ast.walk(tree):
    if isinstance(node, ast.Compare):
        for op in node.ops:
            if isinstance(op, ast.In):
                in_operators.append(node)
            elif isinstance(op, ast.NotIn):
                not_in_operators.append(node)

assert len(in_operators) >= 2, f'Should use "in" operator at least twice (steps 1, 3, 4). Found {len(in_operators)}'
assert len(not_in_operators) >= 1, f'Should use "not in" operator at least once (step 2). Found {len(not_in_operators)}'

print('TEST_PASSED: Using membership operators (in/not in)')
